END_VAR
VAR_OUTPUT
    MotorForward    : BOOL;
    MotorReverse    : BOOL;
    kick            : BOOL;
    CompletionLight : BOOL;
    firingTemp      : REAL;
END_VAR
VAR
    State           : EState := EState.IDLE;
    tmp_WashTrig    : R_TRIG;
    tmp_FiringTrig  : R_TRIG;
    tmp_WeightTrig  : R_TRIG;
