            MotorForward := FALSE;
            MotorReverse := FALSE;
            kick := FALSE;
            firingTemp := 0.0;
            IF SensorFeed THEN
                State := EState.WASH;
            END_IF

        EState.WASH:
            IF NOT MotorForward AND SensorFeed THEN
                MotorForward := TRUE;
            END_IF
            IF SensorWash THEN
                MotorForward := FALSE;
                State := EState.WEIGH;
            END_IF

        EState.WEIGH:
            kick := FALSE;
            IF NOT MotorForward AND SensorWash THEN
                MotorForward := TRUE;
            END_IF
            IF SensorWeight THEN
                MotorForward := FALSE;
                State := EState.FIRING;
            END_IF

        EState.FIRING:
            IF weight < 100.0 OR weight > 200.0 THEN
                kick := TRUE;
            END_IF
            IF NOT MotorForward AND SensorWeight THEN
                MotorForward := TRUE;
            END_IF
            IF SensorFiring THEN
                MotorForward := FALSE;
                State := EState.OUTPUT;
            END_IF

        EState.OUTPUT:
            IF SensorOutput THEN
                MotorForward := FALSE;
                CompletionLight := TRUE;
                State := EState.IDLE;
            END_IF
    END_CASE
END_IF
